from itertools import combinations

def check_girth(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check for triangles (cycle of length 3)
    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > v and w in adj[u]:
                        return False  # Triangle found

    # Check for 4-cycles
    # A 4-cycle exists if two vertices have at least 2 common neighbors
    for u in range(n):
        for v in range(u+1, n):
            common = len(set(adj[u]) & set(adj[v]))
            if common >= 2:
                return False  # 4-cycle found
    return True

# Try to find a 4-regular graph on 8 vertices with girth >= 5
# This is equivalent to finding a 4-regular graph with no 3-cycles or 4-cycles
# Let's use a simple backtracking or constraint solver

from pysat.solvers import Glucose3
from pysat.card import CardEnc

n = 8
degree = 4

# Variables: x_{u,v} for 0 <= u < v < n
var_map = {}
idx = 0
for u in range(n):
    for v in range(u+1, n):
        var_map[(u, v)] = idx + 1
        idx += 1

solver = Glucose3()

# Degree constraints: each vertex has exactly degree 4
for u in range(n):
    vars_u = []
    for v in range(n):
        if u < v:
            vars_u.append(var_map[(u, v)])
        elif v < u:
            vars_u.append(var_map[(v, u)])

    # Exactly 4 edges incident to u
    clauses = CardEnc.equals(lits=vars_u, bound=degree, encoding=1)
    for clause in clauses.clauses:
        solver.add_clause(clause)

# No triangles: for any u < v < w, not all three edges (u,v), (v,w), (u,w) can be present
for u in range(n):
    for v in range(u+1, n):
        for w in range(v+1, n):
            solver.add_clause([-var_map[(u, v)], -var_map[(u, w)], -var_map[(v, w)]])

# No 4-cycles: for any u < v < w < x, we can't have edges forming a 4-cycle
# A 4-cycle on vertices u, v, w, x can be formed in 3 ways:
# (u,v), (v,w), (w,x), (x,u)
# (u,v), (v,x), (x,w), (w,u)
# (u,w), (w,v), (v,x), (x,u)
# We need to forbid all of these
for u in range(n):
    for v in range(u+1, n):
        for w in range(v+1, n):
            for x in range(w+1, n):
                # Cycle u-v-w-x-u
                solver.add_clause([-var_map[(u, v)], -var_map[(v, w)], -var_map[(w, x)], -var_map[(u, x)]])
                # Cycle u-v-x-w-u
                solver.add_clause([-var_map[(u, v)], -var_map[(v, x)], -var_map[(w, x)], -var_map[(u, w)]])
                # Cycle u-w-v-x-u
                solver.add_clause([-var_map[(u, w)], -var_map[(v, w)], -var_map[(v, x)], -var_map[(u, x)]])

if solver.solve():
    model = solver.get_model()
    edges = []
    for (u, v), var in var_map.items():
        if var in model:
            edges.append((u, v))
    print("SATISFIABLE")
    print(edges)
else:
    print("UNSATISFIABLE")
